1	import { copyFileSync, mkdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
2	import { join, dirname } from 'node:path';
3	import { fileURLToPath, pathToFileURL } from 'node:url';
4	import { computeVendorSet, SHARED_SUBDIR } from '../../../vendoring/compute-vendor-set.mjs';
5	import { loadPacks, resolveDeclaredPacks, packEntryId } from '../../../engine/pack_loader/pack-registry.mjs';
6	import { ENGINE_VERSION } from '../../../engine/version.mjs';
7	import { isVersion, versionAbove } from '../../../engine/version.mjs';
8	import { DECLARATION_FILE } from '../../../engine/checks/helpers/active-migrations.mjs';
9	import { settingsPath } from '../../../engine/settings-file.mjs';
10	import { installedVersions, hasInstalledMount, withInstalledVersions } from '../../../engine/installed-versions.mjs';
11	import { NEEDS_HUMAN, runSelfTest, deliveryDecision } from './engine-update.mjs';
12	import { isPackFile } from './pack-update.mjs';
13	
14	// INSTALL = THE UPDATE FLOW FROM VERSION ZERO (docs/versioned-updates/DESIGN.md §4),
15	// with one difference that is not an optimisation but a correctness rule:
16	//
17	//   **AN INSTALL RUNS NO MIGRATIONS** (owner decision 9). The vendored content is
18	//   already the newest shape, so there is no older state to migrate. Replaying
19	//   history onto a fresh install is not merely wasted work — a record assumes the
20	//   shapes ITS ERA produced, and an empty repo is not one of them, so the replay is
21	//   a hazard. The install fetches no records and stamps the LATEST version directly;
22	//   migrations exist for repos installed at an older one.
23	//
24	// Everything else is the pack flow's: same vendor set, same self-test gate, same
25	// terminals. What differs is only where it starts.
26	//
27	// AN INSTALL IS NOT AN UPDATE IN DISGUISE. A pack the repo already has a version for
28	// is refused rather than reinstalled: reinstalling would stamp the newest version
29	// while skipping every record between, which is exactly how a member ends up
30	// claiming a state it was never migrated into.
31	const canonRoot = dirname(dirname(dirname(dirname(fileURLToPath(import.meta.url))))); // <canon>/packs/claudinite-lifecycle/updates/<this file>
32	
33	const outcome = (status, detail, extra = {}) => ({ status, detail, ...extra });
34	
35	// Which of the requested ids this repo can actually install, and why the rest are
36	// refused. Pure over the pack set and the stamp, so the judgment is testable with
37	// no repo on disk.
38	export function planInstall(packs, ids, installed, { engineVersion = ENGINE_VERSION } = {}) {
39	  const byId = new Map(packs.map((p) => [p.id, p]));
40	  const stamped = installed?.packVersions ?? {};
41	  const install = [];
42	  const refused = [];
43	  for (const id of ids ?? []) {
44	    const pack = byId.get(id);
45	    if (!pack) { refused.push({ id, why: `"${id}" names no canon pack` }); continue; }
46	    if (isVersion(stamped[id])) {
47	      refused.push({ id, why: `"${id}" is already installed at version ${stamped[id]} — that is an update, not an install` });
48	      continue;
49	    }
50	    const needs = pack.minEngineVersion;
51	    if (isVersion(needs) && versionAbove(needs, engineVersion)) {
52	      refused.push({ id, why: `"${id}" needs engine ${needs}; this repo runs engine ${engineVersion}` });
53	      continue;
54	    }
55	    install.push({ id, version: pack.version ?? null });
56	  }
57	  return { install, refused };
58	}
59	
60	// The questions this install cannot answer for the repo. An interview is not a
61	// special terminal (DESIGN §3.9) — unanswered questions end the run exactly like a
62	// red check does: PR open, `needs-human`, stop. It degrades gracefully to async,
63	// which is what the live-session adoption skill could never do.
64	export function unansweredQuestions(packs, entries) {
65	  const byId = new Map(packs.map((p) => [p.id, p]));
66	  const out = [];
67	  for (const entry of entries ?? []) {
68	    const id = packEntryId(entry);
69	    const pack = id === undefined ? undefined : byId.get(id);
70	    if (!pack?.questions?.length) continue;
71	    const answers = (typeof entry === 'object' && entry?.answers) || {};
72	    for (const q of pack.questions) {
73	      if (!q?.id || answers[q.id] !== undefined) continue;
74	      out.push({ pack: id, question: q.id, prompt: q.prompt ?? '' });
75	    }
76	  }
77	  return out;
78	}
79	
80	// Install `ids` into `targetRoot`: declare them, vendor their content, stamp their
81	// latest versions, gate, and report. `dryRun` judges everything and writes nothing.
82	export async function installPacks(targetRoot, ids, {
83	  today, dryRun = false, delivery = 'auto-merge', forceMergeOnRedCi = false, selfTestRun, packs: packSet,
84	} = {}) {
85	  const settingsFile = settingsPath(targetRoot);
86	  if (!existsSync(settingsFile)) {
87	    return outcome(NEEDS_HUMAN, `${targetRoot} has no ${DECLARATION_FILE} — adoption seeds the declaration first`);
88	  }
89	  let raw;
90	  try { raw = JSON.parse(readFileSync(settingsFile, 'utf8')); }
91	  catch (e) { return outcome(NEEDS_HUMAN, `${DECLARATION_FILE} is not valid JSON: ${e.message}`); }
92	
93	  // Canonicalized by the shape reader before planInstall sees it: a renamed pack whose
94	  // version sits under the old key would otherwise be "not installed", and installing
95	  // re-stamps it at latest having run none of the records in its gap.
96	  const installed = hasInstalledMount(raw) ? installedVersions(raw) : null;
97	  const engineVersion = isVersion(installed?.engineVersion) ? installed.engineVersion : ENGINE_VERSION;
98	  // `packs` is injectable for the same reason `selfTestRun` is: the seed-op path is
99	  // only reachable through a manifest that declares one, and the canon deliberately
100	  // has none yet.
101	  const packs = packSet ?? await loadPacks();
102	  const { install, refused } = planInstall(packs, ids, installed, { engineVersion });
103	  if (!install.length) {
104	    return outcome(NEEDS_HUMAN, refused.map((r) => r.why).join('; ') || 'nothing to install', { refused });
105	  }
106	
107	  // The declaration first: the vendor set is computed FROM it, so a pack that is not
108	  // declared has no content to lay down.
109	  const declared = Array.isArray(raw.packs) ? [...raw.packs] : [];
110	  for (const { id } of install) {
111	    if (!declared.some((e) => packEntryId(e) === id)) declared.push(id);
112	  }
113	
114	  const entries = resolveDeclaredPacks(declared, packs);
115	  const unanswered = unansweredQuestions(packs, entries);
116	
117	  // THE `requires` CLOSURE IS INSTALLED TOO, and stamped. A pack pulled in by another
118	  // (git-github via basics) has its content vendored either way — `computeVendorSet`
119	  // resolves the same closure — so stamping only the ids a caller happened to NAME
120	  // would leave the rest installed-but-unversioned. That is the same silent hole this
121	  // CLI was written to close, one level down: unversioned means the update flow reads
122	  // `from: null` and falls back to the landed-date window instead of comparing
123	  // numbers. A repo's real stamp already reflects this — the canary carries
124	  // `git-github: 1` without declaring it — so the arithmetic here is catching up with
125	  // what the fleet has always meant.
126	  const named = new Set(install.map((i) => i.id));
127	  const pulled = entries.map(packEntryId).filter((id) => typeof id === 'string' && !named.has(id));
128	  install.push(...planInstall(packs, pulled, installed, { engineVersion }).install);
129	
130	  // No `installed` passed: an install fetches no migration records at all, whatever
131	  // the repo's stamp says. The set is content only.
132	  const { files, errors } = await computeVendorSet(declared, { today, installed: { engineVersion, packVersions: forcedCurrent(packs) } });
133	  if (errors.length) return outcome(NEEDS_HUMAN, errors.map((e) => e.what).join('; '), { errors, refused });
134	
135	  const ourFiles = files.filter((f) => install.some(({ id }) => isPackFile(f, id)));
136	  const records = ourFiles.filter((f) => f.includes('/migrations/'));
137	  if (dryRun) {
138	    return outcome('ok', `would install ${install.map((i) => i.id).join(', ')}`,
139	      { install, refused, unanswered, files: ourFiles.length, records: records.length, dryRun: true });
140	  }
141	
142	  const sharedDir = join(targetRoot, SHARED_SUBDIR);
143	  for (const file of ourFiles) {
144	    const dest = join(sharedDir, file);
145	    mkdirSync(dirname(dest), { recursive: true });
146	    copyFileSync(join(canonRoot, file), dest);
147	  }
148	
149	  // Stamp the LATEST version directly — the install's whole claim. Nothing is
150	  // migrated into it, so nothing may imply it was.
151	  const next = JSON.parse(readFileSync(settingsFile, 'utf8'));
152	  // THE RESOLVED ENTRIES, not the bare `declared` list: every pack this run stamps
153	  // needs an entry to carry its version, and a pack pulled in through another's
154	  // `requires` is installed exactly as much as a named one. That is not a
155	  // declaration made on the repo's behalf — `via` is what says so, written by
156	  // `resolveDeclaredPacks` and read by anything that must tell a chosen pack from an
157	  // inferred one. It is also what `--init` already seeds, so the two writers agree.
158	  //
159	  // Before #1252 the closure's versions lived in a central map that needed no entry,
160	  // which is why the two could disagree at all: a pack could be installed, stamped,
161	  // and named nowhere in the file it was stamped in.
162	  next.packs = entries;
163	  const packVersions = {};
164	  for (const { id, version } of install) if (version !== null) packVersions[id] = version;
165	  writeFileSync(settingsFile, `${JSON.stringify(withInstalledVersions(next, { packVersions }), null, 2)}\n`);
166	
167	  // Seed ops: the install-only effects the repo owns from here (DESIGN §4). Written
168	  // ONLY when the dest is absent — a seeded file is the member's from the moment it
169	  // lands, and an install that overwrote one would be doing exactly what the
170	  // seeded-vs-converged distinction exists to prevent.
171	  const seeded = [];
172	  for (const { id } of install) {
173	    const pack = packs.find((p) => p.id === id);
174	    for (const { template, dest } of pack?.seedOps ?? []) {
175	      const from = join(canonRoot, 'packs', id, template);
176	      const to = join(targetRoot, dest);
177	      if (!existsSync(from) || existsSync(to)) continue;
178	      mkdirSync(dirname(to), { recursive: true });
179	      copyFileSync(from, to);
180	      seeded.push(dest);
181	    }
182	  }
183	
184	  // Steps only a human can perform, collected from the packs actually installed
185	  // (`adoptionHandover`). Adoption is the one moment someone is present and the pack
186	  // is new, so this is where they get said; carrying them only in a pack's README
187	  // means the adopter meets them after the deploy has already failed.
188	  //
189	  // Reported, never acted on: nothing here can flip a repository setting, and a flow
190	  // that pretended to would be worse than one that names the gap.
191	  const handover = [];
192	  for (const { id } of install) {
193	    const pack = packs.find((p) => p.id === id);
194	    for (const step of pack?.adoptionHandover ?? []) handover.push({ pack: id, ...step });
195	  }
196	
197	  const selftest = runSelfTest(targetRoot, selfTestRun);
198	  const decision = unanswered.length
199	    ? { action: 'needs-human', why: `${unanswered.length} adoption question(s) unanswered: ${unanswered.map((u) => `${u.pack}/${u.question}`).join(', ')}` }
200	    : deliveryDecision({ selftestOk: selftest.ok, delivery, forceMergeOnRedCi });
201	
202	  return outcome(decision.action === 'needs-human' ? NEEDS_HUMAN : 'ok', decision.why, {
203	    install, refused, unanswered, seeded, handover, files: ourFiles.length, selftest, decision,
204	    // An install is where the pack's rules FIRST meet this repo's content, so the
205	    // apply stage is always the next step — there is no "nothing moved" case here.
206	    applyStage: { needed: true, packs: install.map((i) => i.id), why: 'the pack\'s rules meet this repo for the first time' },
207	  });
208	}
209	
210	// The version map that makes the record gate answer "nothing applies": every pack at
211	// its newest. An install must fetch no records, and saying so through the same
212	// predicate the other flows use is better than a second code path that could drift
213	// from it.
214	const forcedCurrent = (packs) => Object.fromEntries(packs.map((p) => [p.id, p.version ?? 0]));
215	
216	// CLI: `node install.mjs --target <dir> <pack-id>…` — install packs into a repo, from
217	// a fresh canon clone. Run by the adoption skills (adopt-pack, adopt-claudinite).
218	//
219	// WHY THIS EXISTS AT ALL (#768). The skills used to converge an adoption by hand:
220	// fetch canon, run `vendoring/apply-vendor-set.mjs`, advance the stamp. That lays the
221	// pack's FILES down correctly and gets one thing wrong that nothing notices for weeks
222	// — but not the thing this comment used to claim. `applyVendor` DOES write
223	// `claudinite.packVersions`; `computeVendorSet` returns the version of every declared
224	// pack and the writer stamps the lot in the same pass. The hazard is the opposite of
225	// "unversioned", and worse:
226	//
227	//   IT STAMPS EVERY DECLARED PACK AT THE NEWEST VERSION, whether or not the records
228	//   between were ever applied. `migrationApplies` is `want > have`, so the moment the
229	//   stamp reaches the record's own version the record stops applying — not for this
230	//   cycle, but forever. A member converged this way ends up CLAIMING a version whose
231	//   shape it was never migrated into, and nothing downstream can tell the difference,
232	//   because the stamp is the only thing that remembers.
233	//
234	// At version zero that is exactly right, and it is what an install means: no older
235	// state exists, so there is nothing to skip. Run it over a repo that already has a
236	// stamp and the same behaviour silently burns that repo's pending records — which is
237	// why `planInstall` refuses an already-installed pack rather than treating this as an
238	// optimisation (see the exit note at the bottom of `main`, which had this right).
239	//
240	// One runner, one stamp. The skills describe intent and hand-offs; the arithmetic of
241	// what version a repo is now at belongs here, where the update flows read it from.
242	async function main() {
243	  const argv = process.argv.slice(2);
244	  const flag = (name) => { const i = argv.indexOf(name); return i === -1 ? null : argv[i + 1] ?? null; };
245	  const targetRoot = flag('--target') ?? process.env.CLAUDINITE_REPO_ROOT ?? process.cwd();
246	  const dryRun = argv.includes('--dry-run');
247	  const consumed = new Set(['--target', targetRoot, '--dry-run', '--delivery', flag('--delivery')]);
248	  const ids = argv.filter((a) => !a.startsWith('--') && !consumed.has(a));
249	  if (!ids.length) {
250	    console.error('install: name at least one pack id — `node install.mjs --target <dir> <pack-id>…`');
251	    process.exit(1);
252	  }
253	
254	  const r = await installPacks(targetRoot, ids, { dryRun, delivery: flag('--delivery') ?? 'auto-merge' });
255	  for (const i of r.install ?? []) console.log(`install: ${i.id} → version ${i.version ?? 'unversioned'}`);
256	  for (const f of r.refused ?? []) console.log(`install: REFUSED ${f.id} — ${f.why}`);
257	  for (const s of r.seeded ?? []) console.log(`install: seeded ${s}`);
258	
259	  // Loud, and last before the status line: these are the steps the adoption cannot
260	  // take, and the adopting session owes each one its own tracking issue.
261	  if ((r.handover ?? []).length) {
262	    console.log(`\ninstall: ${r.handover.length} step(s) only a human can do — open a tracking issue for these:`);
263	    for (const h of r.handover) {
264	      console.log(`  [ ] (${h.pack}) ${h.step}`);
265	      if (h.breaks) console.log(`        while off: ${h.breaks}`);
266	      if (h.done) console.log(`        done when: ${h.done}`);
267	    }
268	    console.log('');
269	  }
270	  console.log(`install: ${r.status} — ${r.detail}`);
271	
272	  // A refusal is not a partial success. `planInstall` refuses a pack whose engine is
273	  // too old, an unknown id, and a pack already installed (that is an UPDATE, and
274	  // running an install over it would restamp the repo to the newest version while
275	  // skipping every record in between). Exiting 0 there would let a caller's `&&`
276	  // chain carry on as if the pack were adopted.
277	  if (r.status === NEEDS_HUMAN || (r.refused ?? []).length) process.exit(1);
278	}
279	
280	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
281	  main().catch((e) => { console.error(`install failed: ${e.message}`); process.exit(1); });
282	}
283

