370	// `{ id, config?, rules?, accept?, via? }` carrying that pack's own settings
371	// (see engine/checks/README.md). This is the one id-extractor every reader shares, so
372	// raw-JSON consumers (the SessionStart hooks, the fleet signal probe) and the
373	// engine agree on both shapes — and on both declaration forms: it returns the
374	// BARE pack id, stripping a `local_packs/` namespace where one is declared.
375	// Returns undefined for a malformed entry.
376	// A declaration written before a canon pack was renamed resolves to the pack's
377	// CURRENT id here (renamed-packs.mjs), so activation, config lookup and the vendor
378	// set all agree on one spelling no matter which one the member wrote. A LOCAL pack
379	// is exempt: its namespace belongs to the repo, so `local/core` stays `core`.
380	// A local pack declared BARE cannot be told apart from a canon one at this seam and
381	// is canonicalized with the rest — which is harmless while the shadow guard in
382	// discoverPacks keeps a local id from claiming a canon one.
383	export const packEntryId = (entry) => {
384	  const raw = typeof entry === 'string'
385	    ? entry
386	    : entry !== null && typeof entry === 'object' && typeof entry.id === 'string'
387	      ? entry.id
388	      : undefined;
389	  if (raw === undefined) return undefined;
390	  const bare = stripLocalPrefix(raw);
391	  return bare === raw ? canonicalPackId(bare) : bare;
392	};
393	
394	// No pack is active by default. Activation is exactly the project's declaration
395	// in .claudinite-settings.json (bootstrap's --init seeds the default-on packs).
396	export const isActive = (pack, config) =>
397	  (config.packs ?? []).some((entry) => packEntryId(entry) === pack.id);
398	
399	// The MOUNTED SKILL SET: the union of the given packs' bundled skills, as a
400	// Map(name -> the skill's directory). A bundled skill is `<pack>/skills/<name>/`
401	// carrying a SKILL.md — the one shape, canon and local alike (#385). The packs are
402	// taken in the caller's order and the FIRST occurrence of a name wins, so a caller
403	// passing canon packs before local ones resolves a shared name to canon.
404	//
405	// Read off each pack's own `skills`, which the convention fills from that same
406	// directory listing — so this is the tree's answer for every ordinary pack, and a
407	// manifest that withholds a name is honoured here rather than quietly re-derived.
408	//
409	// One definition, two readers: the SessionStart mount hook (mount-skills.mjs) turns
410	// it into `.claude/skills/` symlinks, and the usage fold asks it which skill names a
411	// typed `/command` could possibly be. The mounts themselves are gitignored session
412	// state, so anything reasoning about "what is mounted here" must ask the registry —
413	// this function — and never the mount directory.
414	export function bundledSkillSources(packs) {
415	  const byName = new Map();
416	  for (const pack of packs) {
417	    for (const name of pack.skills ?? []) {
418	      if (byName.has(name)) continue;
419	      const dir = join(pack.dir, 'skills', name);
420	      if (existsSync(join(dir, 'SKILL.md'))) byName.set(name, dir);
421	    }
422	  }
423	  return byName;
424	}
425	
426	// Import closure. A pack can't be imported without the packs it requires: a
427	// release pack builds on its coding pack, a project-class pack on the framework
428	// pack that implements it. A pack names those in its `requires` list.
429	// Given the entries a project declares (id strings or entry objects), return
430	// that set plus every pack reachable through `requires` (transitively).
431	// Declared entries keep their order; each pack's pulled-in dependencies land
432	// right after it, deterministically. This runs when the declaration is
433	// WRITTEN — bootstrap's `--init` and the baselining backfill — so a pack's
434	// prerequisites are materialized into .claudinite-settings.json, visible and
435	// droppable like every other entry (the same reason a seeded pack is written
436	// explicitly rather than defaulted), never resolved implicitly at run time.
437	//
438	// Provenance: a materialized dependency is written as `{ id, via: [...] }`,
439	// `via` naming the resolved packs that directly require it — the file itself
440	// answers "why is this pack declared". An entry already carrying `via`
441	// self-identifies as materialized, so its `via` is recomputed to stay accurate
442	// as dependents come and go (an empty recomputed `via` marks an orphan the
443	// project can drop); a user-authored entry (no `via`) is kept verbatim.
444	// A declared id is kept verbatim even if unknown (settings validation flags
445	// that); a dependency is only materialized when it names a real pack; an
446	// entry with no usable id (a settings error) is preserved untouched — the
447	// writer must never drop what it can't interpret.
448	export function resolveDeclaredPacks(declared, packs) {
449	  const byId = new Map(packs.map((p) => [p.id, p]));
450	  const declaredIds = new Set(declared.map(packEntryId).filter((id) => id !== undefined));
451	  const entryById = new Map();
452	  for (const entry of declared) {
453	    const id = packEntryId(entry);
454	    if (id !== undefined && !entryById.has(id)) entryById.set(id, entry);
455	  }
456	  const orderedIds = [];
457	  const seen = new Set();
458	  const visit = (id) => {
459	    if (seen.has(id)) return;
460	    if (!declaredIds.has(id) && !byId.has(id)) return; // don't materialize a phantom dep
461	    seen.add(id);
462	    orderedIds.push(id);
463	    for (const dep of byId.get(id)?.requires ?? []) visit(dep);
464	  };
465	  for (const entry of declared) {
466	    const id = packEntryId(entry);
467	    if (id !== undefined) visit(id);
468	  }
469	  const via = (id) => orderedIds.filter((p) => byId.get(p)?.requires?.includes(id)).sort();
470	  const resolved = orderedIds.map((id) => {
471	    const entry = entryById.get(id);
472	    if (entry === undefined) return { id, via: via(id) };
473	    if (typeof entry === 'object' && 'via' in entry) return { ...entry, via: via(id) };
474	    return entry;
475	  });
476	  return [...resolved, ...declared.filter((entry) => packEntryId(entry) === undefined)];
477	}
